/* Generated by the static build. Contains application assets only, never policy data. */
const RELEASE = __RELEASE__;
const PRECACHE = __PRECACHE__;
const ALLOWED = new Set(PRECACHE);

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const cache = await caches.open(RELEASE);
    await Promise.all(PRECACHE.map(async path => {
      const response = await fetch(new Request(path, { cache: "reload", credentials: "omit" }));
      if (!response.ok || response.redirected) throw new Error("Offline asset could not be prepared");
      const type = response.headers.get("content-type") || "";
      if ((path === "/" || path.endsWith(".html")) && !type.includes("text/html")) throw new Error("Invalid application shell");
      if (path.endsWith(".js") && !/(?:javascript|ecmascript)/i.test(type)) throw new Error("Invalid script");
      if (path.endsWith(".css") && !type.includes("text/css")) throw new Error("Invalid stylesheet");
      await cache.put(path, response);
    }));
    // An updated version waits for the user's explicit choice.
  })());
});
self.addEventListener("message", event => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
});
self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith("policy-tree-local-") && key !== RELEASE).map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});
self.addEventListener("fetch", event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== self.location.origin || url.search || !ALLOWED.has(url.pathname)) return;
  event.respondWith((async () => {
    const cache = await caches.open(RELEASE);
    return await cache.match(url.pathname) || fetch(request);
  })());
});
